const assert = require('node:assert/strict');
const {runTarget, runAdjacent} = require('./src/temporal-flow');
(async () => {
  for (const clickBeforeReady of [true, false]) {
    for (const loadedFlag of [true, false]) {
      const result = await runTarget({clickBeforeReady, loadedFlag});
      const value = loadedFlag ? 'premium-action' : 'none';
      assert.deepEqual(result, {value, events:[value]});
    }
  }
  assert.deepEqual(await runAdjacent({clickBeforeReady:true}), {value:'emergency-action', events:['emergency-action']});
  assert.deepEqual(await runAdjacent({clickBeforeReady:false}), {value:'none', events:['none']});
  console.log('Temporal action checks passed');
})().catch(error => {console.error(error); process.exitCode=1});
